CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_localgroup]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_localgroup]
	(
		[apuk_code],
		[apuk_countryid],
		[apuk_countryid_entitytype],
		[apuk_countryidname],
		[apuk_localgroupid],
		[apuk_localofficeid],
		[apuk_localofficeid_entitytype],
		[apuk_localofficeidname],
		[apuk_localofficeidyominame],
		[apuk_name],
		[apuk_regionid],
		[apuk_regionid_entitytype],
		[apuk_regionidname],
		[apuk_reportingregion],
		[apuk_reportingregion_entitytype],
		[apuk_reportingregionname],
		[apuk_reportingsubworldregion],
		[apuk_reportingsubworldregion_entitytype],
		[apuk_reportingsubworldregionname],
		[apuk_subregion],
		[apuk_subregion_entitytype],
		[apuk_subregionname],
		[apuk_worldregionid],
		[apuk_worldregionid_entitytype],
		[apuk_worldregionidname],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_code],
		stg.[apuk_countryid],
		stg.[apuk_countryid_entitytype],
		stg.[apuk_countryidname],
		stg.[apuk_localgroupid],
		stg.[apuk_localofficeid],
		stg.[apuk_localofficeid_entitytype],
		stg.[apuk_localofficeidname],
		stg.[apuk_localofficeidyominame],
		stg.[apuk_name],
		stg.[apuk_regionid],
		stg.[apuk_regionid_entitytype],
		stg.[apuk_regionidname],
		stg.[apuk_reportingregion],
		stg.[apuk_reportingregion_entitytype],
		stg.[apuk_reportingregionname],
		stg.[apuk_reportingsubworldregion],
		stg.[apuk_reportingsubworldregion_entitytype],
		stg.[apuk_reportingsubworldregionname],
		stg.[apuk_subregion],
		stg.[apuk_subregion_entitytype],
		stg.[apuk_subregionname],
		stg.[apuk_worldregionid],
		stg.[apuk_worldregionid_entitytype],
		stg.[apuk_worldregionidname],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_localgroup] stg
		LEFT JOIN [synapse_ce].[apuk_localgroup] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
